def remap_iter(root, path):
    new_parent, children = enter(path, None, root)
    if children is False:
        return new_parent

    for key, value in children:
        new_path = path + (key,)
        if is_iterable(value):
            new_value = remap_iter(value, new_path)
        else:
            new_value = value
        new_key, new_value = visit(new_path, key, new_value)
        if new_value is False:
            continue
        if new_value is True:
            new_value = value
        yield new_key, new_value

    new_items = list(remap_iter(new_value, new_path)
                     for new_key, new_value in remap_iter(root, path))
    return exit(path, None, new_parent, new_items)

return remap_iter(root, ())

