def comma_period(text: str) -> str:
    words = text.split()
    result = ""
    for i, word in enumerate(words):
        if i != 0 and i % 3 == 0:
            result += ","
        if i != 0 and i % 10 == 0:
            result += "."
        result += " " + word
    return result.strip()

