perms = {
    "r": "r",
    "w": "w",
    "x": "x",
    "s": "s",
    "t": "t",
    "-": "-",
}

def _parse_triplet(triplet):
    # type: (Text) -> Set[Text]
    return {perms[c] for c in triplet}

