    else:
        if buffer:
            res.extend(base64_utf7_encode(buffer))
            buffer = []
        res.append('&' + base64_utf7_encode(c) + '-')
# If there's anything left in the buffer, encode it
if buffer:
    res.extend(base64_utf7_encode(buffer))
return b''.join(res)

