    methods = []
    for method_name in dir(component):
        if not method_name.startswith('_'):
            method = getattr(component, method_name)
            if inspect.ismethod(method):
                source_info = _get_source_info(method)
                method_info = MiddlewareMethodInfo(method_name, source_info)
                methods.append(method_info)
    class_info = MiddlewareClassInfo(name, _get_source_info(component), methods)
    middleware_classes.append(class_info)

return MiddlewareInfo(middleware_tree, middleware_classes, False)

