class SaveCwdContextManager(object):
    def __enter__(self):
        self.saved_cwd = os.getcwd()

    def __exit__(self, exc_type, exc_value, traceback):
        os.chdir(self.saved_cwd)

return SaveCwdContextManager()

class CWDContextManager(object):
    def __enter__(self):
        self.cwd = os.getcwd()

    def __exit__(self, type, value, traceback):
        os.chdir(self.cwd)

return CWDContextManager()

