    try:
        extension_class = entry_point.load()
        if issubclass(extension_class, Extension):
            extension = extension_class()
            config_schema = extension.get_config_schema()
            config_defaults = extension.get_default_config()
            command = extension.get_command()
            extensions.append(
                ExtensionData(
                    extension=extension,
                    entry_point=entry_point,
                    config_schema=config_schema,
                    config_defaults=config_defaults,
                    command=command,
                )
            )
        else:
            logger.warning(
                "Ignoring entry point %s: not a valid extension class",
                entry_point.name,
            )
    except Exception:
        logger.exception(
            "Loading extension %s failed with an exception",
            entry_point.name,
        )

return extensions

