result = {}
for name, value in os.environ.items():
    if name.startswith("XDG_"):
        key = name.replace("XDG_", "").lower()
        result[key] = pathlib.Path(value).expanduser()

xdg_config_dir = result.get("config_dir")
if xdg_config_dir:
    result.update(_get_user_dirs(xdg_config_dir))

return result

result = {}
xdg_config_home = os.environ.get("XDG_CONFIG_HOME") or pathlib.Path.home() / ".config"
result["XDG_CONFIG_HOME"] = pathlib.Path(xdg_config_home).resolve()

for k, v in os.environ.items():
    if k.startswith("XDG_") and k.endswith("_DIR"):
        result[k] = pathlib.Path(v).expanduser().resolve()

user_dirs = _get_user_dirs(result["XDG_CONFIG_HOME"])
result.update(user_dirs)

return result

